import json
import time

URL = "https://chaoxian.com.vn/dat-ban"
BRANCH_VALUE = "68737cd823d94c3bb82bc42a"  # Chao Xian Kim Mã, như bản cũ
POLL_TIMEOUT = 15.0
POLL_STEP = 0.2
EMAIL_SEL_IDS = []  # Trang không có ô email (đã kiểm tra trong danh sách ô), nên bỏ qua


def wait_until(expr, timeout=POLL_TIMEOUT, step=POLL_STEP):
    end = time.time() + timeout
    while True:
        try:
            if js(expr):
                return True
        except Exception:
            pass
        if time.time() >= end:
            return False
        time.sleep(step)


def wait_or_raise(expr, what):
    if not wait_until(expr):
        raise RuntimeError(f"Timeout chờ: {what}")


def get_value(elem_id):
    return js(f"""(() => {{
      const e = document.getElementById({json.dumps(elem_id)});
      return e ? e.value : null;
    }})()""")


def pick_select(sel_id, candidates):
    cands = [str(c) for c in candidates]
    expr = """(() => {
      const s = document.getElementById(%s);
      if (!s) return {err: 'missing'};
      const cands = %s;
      const norm = x => (x == null ? '' : String(x)).trim().toLowerCase();
      const opts = [...s.options];
      let o = null;
      for (const c of cands) {
        const nc = norm(c);
        if (!nc) continue;
        o = opts.find(p => norm(p.value) === nc || norm(p.text) === nc);
        if (o) break;
      }
      if (!o) for (const c of cands) {
        const nc = norm(c);
        if (!nc) continue;
        o = opts.find(p => norm(p.text).includes(nc) || norm(p.value).startsWith(nc));
        if (o) break;
      }
      if (!o) return {err: 'nomatch', opts: opts.map(p => [p.value, p.text])};
      s.value = o.value;
      s.dispatchEvent(new Event('input', {bubbles: true}));
      s.dispatchEvent(new Event('change', {bubbles: true}));
      return {value: s.value, text: o.text};
    })()""" % (json.dumps(sel_id), json.dumps(cands, ensure_ascii=False))
    res = js(expr)
    if not isinstance(res, dict) or 'err' in res:
        raise RuntimeError(f"{sel_id}: {res}")
    return res


def press_backspace():
    cdp('Input.dispatchKeyEvent', type='rawKeyDown', key='Backspace',
        code='Backspace', windowsVirtualKeyCode=8)
    cdp('Input.dispatchKeyEvent', type='keyUp', key='Backspace',
        code='Backspace', windowsVirtualKeyCode=8)


def set_value_native(elem_id, text):
    # Gán value qua setter gốc rồi phát input/change, dùng khi gõ phím không ăn
    js(f"""(() => {{
      const e = document.getElementById({json.dumps(elem_id)});
      if (!e) return 0;
      const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(e), 'value');
      d.set.call(e, {json.dumps(text, ensure_ascii=False)});
      e.dispatchEvent(new Event('input', {{bubbles: true}}));
      e.dispatchEvent(new Event('change', {{bubbles: true}}));
      return 1;
    }})()""")


def fill_text(elem_id, text):
    info = js(f"""(() => {{
      const e = document.getElementById({json.dumps(elem_id)});
      if (!e) return null;
      e.scrollIntoView({{block: 'center'}});
      const r = e.getBoundingClientRect();
      return {{x: r.left + r.width / 2, y: r.top + r.height / 2}};
    }})()""")
    if not info:
        raise RuntimeError(f"Không tìm thấy ô {elem_id}")

    # Lần 1: click, chọn hết, gõ
    click_at_xy(info['x'], info['y'])
    time.sleep(0.2)
    cdp('Input.dispatchKeyEvent', type='rawKeyDown', key='a', code='KeyA', commands=['selectAll'])
    cdp('Input.dispatchKeyEvent', type='keyUp', key='a', code='KeyA')
    type_text(text)
    time.sleep(0.2)
    if get_value(elem_id) == text:
        return

    # Lần 2: xóa hết bằng Backspace rồi gõ lại
    cur = get_value(elem_id) or ''
    for _ in range(len(cur) + 3):
        press_backspace()
    type_text(text)
    time.sleep(0.2)
    if get_value(elem_id) == text:
        return

    # Lần 3: gán trực tiếp
    set_value_native(elem_id, text)
    time.sleep(0.2)


# 1. Mở trang và chờ form
new_tab(URL)
wait_for_load()
wait_or_raise(
    "(() => !!document.getElementById('selectCoso') && !!document.getElementById('nameOrder') "
    "&& !!document.getElementById('sdtOrder') && !!document.getElementById('selectHour'))()",
    "form đặt bàn")

# 2. Chi nhánh
print("branch:", pick_select('selectCoso', [BRANCH_VALUE]))
time.sleep(1.0)

# 3. Số người
print("party:", pick_select('selectSoNguoi', [str(PARTY)]))

# 4. Ngày (select ghi "Ngày mai")
print("day:", pick_select('selectDay', ['Ngày mai', '1']))

# 5. Chờ danh sách giờ tải xong rồi chọn giờ
wait_or_raise(f"""(() => {{
  const s = document.getElementById('selectHour');
  if (!s) return false;
  return [...s.options].some(o => o.text.trim() === {json.dumps(HHMM)}
                              || o.value.startsWith({json.dumps(HHMM)}));
}})()""", f"danh sách giờ có {HHMM}")
print("hour:", pick_select('selectHour', [HHMM + ':00', HHMM]))

# Chọn lại số người và ngày nếu việc chọn giờ/chi nhánh làm form reset
party_now = get_value('selectSoNguoi')
if party_now != str(PARTY):
    print("party reset, chọn lại:", pick_select('selectSoNguoi', [str(PARTY)]))
day_now = get_value('selectDay')
if day_now != '1':
    print("day reset, chọn lại:", pick_select('selectDay', ['Ngày mai', '1']))
    wait_or_raise(f"""(() => {{
      const s = document.getElementById('selectHour');
      return !!s && [...s.options].some(o => o.text.trim() === {json.dumps(HHMM)}
                                         || o.value.startsWith({json.dumps(HHMM)}));
    }})()""", f"danh sách giờ có {HHMM} sau khi chọn lại ngày")
    print("hour again:", pick_select('selectHour', [HHMM + ':00', HHMM]))

# 6. Điền các ô
fill_text('nameOrder', NAME)
fill_text('sdtOrder', PHONE)

email_present = bool(js(
    "!!document.querySelector('input[type=email], input[name*=mail], input[id*=mail]')"))
if email_present:
    fill_text_sel = js("""(() => {
      const e = document.querySelector('input[type=email], input[name*=mail], input[id*=mail]');
      return e ? e.id : null;
    })()""")
    if fill_text_sel:
        fill_text(fill_text_sel, EMAIL)
else:
    print("Không có ô email trên trang, bỏ qua.")

js("(() => { if (document.activeElement) document.activeElement.blur(); return 1; })()")
time.sleep(0.3)

# 7. Kiểm tra giá trị
state = js("""(() => {
  const g = id => { const e = document.getElementById(id); return e ? e.value : null; };
  const h = document.getElementById('selectHour');
  const hourText = h && h.selectedOptions[0] ? h.selectedOptions[0].text : null;
  const em = document.querySelector('input[type=email], input[name*=mail], input[id*=mail]');
  return {
    selectCoso: g('selectCoso'),
    selectSoNguoi: g('selectSoNguoi'),
    selectDay: g('selectDay'),
    selectHour: g('selectHour'),
    hourText: hourText,
    nameOrder: g('nameOrder'),
    sdtOrder: g('sdtOrder'),
    email: em ? em.value : null
  };
})()""")
print("state:", state)

errors = []
if state.get('selectCoso') != BRANCH_VALUE:
    errors.append("chi nhánh")
if state.get('selectSoNguoi') != str(PARTY):
    errors.append("số người")
if state.get('selectDay') != '1':
    errors.append(f"ngày (mong đợi {DATE_ISO}/{DATE_DMY} = 'Ngày mai')")
if not state.get('selectHour') or HHMM not in (state.get('hourText') or ''):
    errors.append("giờ")
if state.get('nameOrder') != NAME:
    errors.append("tên")
if state.get('sdtOrder') != PHONE:
    errors.append(f"SĐT (đang là {state.get('sdtOrder')!r})")
if email_present and state.get('email') != EMAIL:
    errors.append("email")

if errors:
    raise RuntimeError("Giá trị không đúng ở: " + ", ".join(errors))

print("Đã điền form đúng. Không bấm gửi.")

